        total = 0
        previous = ordered[0]
        for current in ordered[1:]:
            total += len(current) if current == previous else cls._lcp(
                previous, current
            )
            previous = current
        return total

    @staticmethod
    def _positions(columns):
        """Map stringified column labels to their unique source positions."""
        positions = {}
        for index, column in enumerate(columns):
            positions.setdefault(str(column), []).append(index)
